{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attached directly to user instead of group or role",
      "resource": "aws_iam_user_policy_attachment.privesc3-passrole-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching policies directly to IAM users increases management complexity and the risk of retaining excessive privileges if the user is not properly decommissioned. Best practice is to attach permissions to groups or roles."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc3-passrole-group" {
  name = "fn1-privesc3-partial-group"
}

resource "aws_iam_group_policy_attachment" "privesc3-passrole-group-attach-policy" {
  group      = aws_iam_group.privesc3-passrole-group.name
  policy_arn = aws_iam_policy.fn1-passrole-star.arn
}

resource "aws_iam_group_membership" "privesc3-passrole-user-membership" {
  name = "fn1-privesc3-partial-membership"
  group = aws_iam_group.privesc3-passrole-group.name
  users = [aws_iam_user.fn1-privesc3-partial-user.name]
}",
  "fix_summary": "Replaced the direct user policy attachment with a pattern that attaches the policy to an IAM Group, then adds the existing user to that group. This adheres to least privilege and manageable access control best practices."
}
